//! Runs the generated API key migration against SQLite and checks the store works on top of it.
#![cfg(feature = "api-keys-seaorm")]

use sea_orm_migration::prelude::*;
use sea_orm_migration::sea_orm::{Database, DatabaseConnection};
use std::time::Duration;
use tideway::auth::{ApiKeyConfig, ApiKeyManager, ApiKeyStore, NewApiKey, SeaOrmApiKeyStore};

// The templates are application code generated by the CLI; keep their formatting as shipped.
#[rustfmt::skip]
#[path = "../tideway-cli/templates/backend/migrations/m016_create_api_keys.hbs"]
mod m016_create_api_keys;

struct Migrator;

#[async_trait::async_trait]
impl MigratorTrait for Migrator {
    fn migrations() -> Vec<Box<dyn MigrationTrait>> {
        vec![Box::new(m016_create_api_keys::Migration)]
    }
}

#[tokio::test]
async fn api_key_store_works_on_generated_sqlite_schema() {
    let db = Database::connect("sqlite::memory:").await.unwrap();
    assert_api_key_store(db).await;
}

#[tokio::test]
#[ignore = "requires PostgreSQL via TEST_DATABASE_URL"]
async fn api_key_store_works_on_generated_postgres_schema() {
    let test_db = tideway::testing::TestDb::new_postgres()
        .await
        .expect("create PostgreSQL test database");
    assert_api_key_store(test_db.connection()).await;
}

async fn assert_api_key_store(db: DatabaseConnection) {
    Migrator::up(&db, None).await.unwrap();
    // Rerunning the migration is harmless.
    m016_create_api_keys::Migration
        .up(&SchemaManager::new(&db))
        .await
        .unwrap();

    let manager = ApiKeyManager::new(
        SeaOrmApiKeyStore::new(db.clone()),
        ApiKeyConfig::default().last_used_update_interval(Duration::ZERO),
    );

    let created = manager
        .create(
            NewApiKey::new("org-1", "CI")
                .scopes(["projects:read", "deployments:*"])
                .created_by("user-1")
                .expires_in(Duration::from_secs(3600)),
        )
        .await
        .unwrap();
    let other = manager
        .create(NewApiKey::new("org-1", "Zapier"))
        .await
        .unwrap();
    let foreign = manager
        .create(NewApiKey::new("org-2", "Other"))
        .await
        .unwrap();

    // Round-trips through the database with only the hash stored.
    let stored = manager
        .store()
        .find_api_key(&created.api_key.id)
        .await
        .unwrap()
        .unwrap();
    assert_eq!(stored.scopes, ["projects:read", "deployments:*"]);
    assert_eq!(stored.created_by.as_deref(), Some("user-1"));
    assert!(stored.expires_at.is_some());
    assert!(stored.last_used_at.is_none());
    assert_ne!(stored.key_hash, created.plaintext);

    // Authentication records last use.
    let key = manager.authenticate(&created.plaintext).await.unwrap();
    assert!(key.has_scope("deployments:write"));
    let stored = manager.get("org-1", &key.id).await.unwrap().unwrap();
    assert!(stored.last_used_at.is_some());

    // Listing is per organization.
    let ids: Vec<_> = manager
        .list("org-1")
        .await
        .unwrap()
        .into_iter()
        .map(|key| key.id)
        .collect();
    assert_eq!(ids.len(), 2);
    assert!(ids.contains(&created.api_key.id) && ids.contains(&other.api_key.id));

    // Revocation is org-bound, single-shot, and takes effect immediately.
    assert!(!manager.revoke("org-2", &created.api_key.id).await.unwrap());
    assert!(manager.revoke("org-1", &created.api_key.id).await.unwrap());
    assert!(!manager.revoke("org-1", &created.api_key.id).await.unwrap());
    assert!(manager.authenticate(&created.plaintext).await.is_err());

    // revoke_all skips already-revoked keys and other organizations.
    assert_eq!(manager.revoke_all("org-1").await.unwrap(), 1);
    assert!(manager.authenticate(&other.plaintext).await.is_err());
    assert!(manager.authenticate(&foreign.plaintext).await.is_ok());
}
